def build_graph(edges):
    """Build nodes and length_by_edge dict from a list of (src, dst, weight)."""
    nodes = {}
    length_by_edge = {}
    for src_name, dst_name, weight in edges:
        if src_name not in nodes:
            nodes[src_name] = Node(src_name)
        if dst_name not in nodes:
            nodes[dst_name] = Node(dst_name)
        nodes[src_name].successors.append(nodes[dst_name])
        length_by_edge[(nodes[src_name], nodes[dst_name])] = weight
    return nodes, length_by_edge


